#!/usr/bin/env bash
# Generated by infra.ado bootstrap_generate_playbook_repo. Do not edit by hand.
# Blocks a push that would publish credential files or literal secrets
# (.vault_pass, .vault-pass, plaintext ado-preflight-*.json, tokens, passwords).
# Ansible Vault encrypted files are allowed. Fails closed.
set -u
root="$(git rev-parse --show-toplevel)" || exit 1
zero=0000000000000000000000000000000000000000
revs=()
while read -r _local_ref local_sha _remote_ref _remote_sha; do
  [ "${local_sha:-$zero}" = "$zero" ] && continue   # branch deletion
  revs+=(--rev "$local_sha")
done
[ "${#revs[@]}" -eq 0 ] && exit 0
exec python3 "$root/.githooks/ado_credential_gate.py" --repo "$root" --profile repo "${revs[@]}"
